//#region src/httpStatusToSvtaErrorCode.d.ts
/**
 * Embed an HTTP response status code into the SVTA Network error
 * category, per the external code embedding rule of SVTA2070. HTTP 404
 * becomes 3404.
 *
 * Values outside the valid HTTP status range (integers 100-599) return
 * the unknown network error code (3000) rather than throwing, so error
 * reporting paths cannot fail.
 *
 * @param status - An HTTP response status code (100-599).
 * @returns The SVTA network error code embedding the status.
 *
 * @public
 *
 * @example
 * {@includeCode ../test/httpStatusToSvtaErrorCode.test.ts#example}
 */
export declare function httpStatusToSvtaErrorCode(status: number): number;
